P=(R-mu)@Vt[:8].T  # (N,8)
# correlate with fourier of i and j
ii=idx[:,0]; jj=idx[:,1]
def four(t,k,ph=0): return np.cos(2*np.pi*k*t/113+ph)
import itertools
best=[]
for c in range(8):
    for k in range(1,57):
        for ph in [0,np.pi/2]:
            f=four(ii,k,ph)
            r=np.corrcoef(P[:,c],f)[0,1]
            if abs(r)>0.3: best.append((c,'i',k,round(ph,2),round(r,2)))
print(best[:40])
